  "helpWorkerEarningsTitle": "ਉਜਰਤ ਅਤੇ ਕਮਾਈ ਖਾਤਾ",
  "helpWorkerFairWageDesc": "ഇടനിലക്കാരുടെ കമ്മീഷനില്ല: നിങ്ങളുടെ ആകെ വരുമാനത്തിന്റെ 95% നേരിട്ട് നിങ്ങളുടെ ബാങ്ക്/UPI അക്കൗണ്ടിലേക്ക് എത്തും.",
  "helpWorkerFairWageStep1": "ഉപഭോക്താവ് പണം നൽകിയാലുടൻ 95% തുക നിങ്ങളുടെ അക്കൗണ്ടിൽ എത്തും.",
  "helpWorkerFairWageStep2": "5% തുക പ്ലാറ്റ്‌ഫോം പ്രവർത്തനങ്ങൾക്കും നിങ്ങളുടെ ക്ഷേമനിധിക്കുമായി മാത്രമേ എടുക്കൂ.",
  "helpWorkerFairWageStep3": "നിങ്ങളുടെ ഡാഷ്‌ബോർഡിൽ വരുമാന വിവരങ്ങളും പേസ്ലിപ്പുകളും എപ്പോൾ വേണമെങ്കിലും കാണാം.",
  "helpWorkerFairWageTitle": "ന്യായമായ വേതനവും തത്സമയ വിതരണവും",
  "helpWorkerFeatComplaintsDesc": "പേയ്‌മെന്റ് പ്രശ്‌നങ്ങളോ തർക്കങ്ങളോ ലേബർ ഓഫീസർമാരെ അറിയിക്കുക.",
