  "helpWorkerFeatDashStep1": "ഇന്നത്തെ വരുമാനം, പൂർത്തിയായ ജോലികൾ, റേറ്റിംഗ്, ക്ഷേമനിധി ബാലൻസ് എന്നിവ ഒറ്റനോട്ടത്തിൽ കാണുക.",
